  'tip.minEr': { en: `The State pays no social insurance (PRSI) on top for office holders.`, nl: `De staat betaalt voor ambtsdragers geen sociale verzekering (PRSI) bovenop.`, fr: `L'État ne paie aucune assurance sociale (PRSI) en plus pour les titulaires de charge.` },
